namespace Maracannes {
[InitializeOnLoad] public static partial class MaracannesBuilder {
 const string B="Assets/Maracannes/",T="Assets/Teatro_Centro_SESI/Scenes/Teatro.unity",S=B+"Scenes/Maracannes_Exposicao.unity";
 [Serializable] public class Record {public string id,title,group,path,original,sourceHash,sourceName;public int room,width,height;}
 [Serializable] public class Catalog {public Record[] posters;}
 static Transform root;static Scene scene;static List<MuseumPoint> points;
 static Material wall,walnut,ivory,graphite,brass,red,green,ochre,clay,glass,stone,white,light;
static List<string> report;
 static MaracannesBuilder(){EditorApplication.delayCall+=()=>{if(File.Exists(B+"Documentation/build.request")){AssetDatabase.DeleteAsset(B+"Documentation/build.request");Build();}};}
 // Ferramenta anterior preservada; conversão atual em Atualizar acervo separado.
 public static void Build(){
  if(EditorApplication.isPlaying)throw new InvalidOperationException("Saia de Play antes de construir.");
  var teatro=SceneManager.GetSceneByPath(T);if(!teatro.isLoaded)teatro=EditorSceneManager.OpenScene(T,OpenSceneMode.Additive);
  if(!File.Exists(B+"Documentation/Teatro_Antes_Maracannes.unity"))EditorSceneManager.SaveScene(teatro,B+"Documentation/Teatro_Antes_Maracannes.unity",true);
  scene=SceneManager.GetSceneByPath(S);if(!scene.isLoaded)scene=File.Exists(S)?EditorSceneManager.OpenScene(S,OpenSceneMode.Additive):EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);
  SceneManager.SetActiveScene(scene);var old=scene.GetRootGameObjects().FirstOrDefault(g=>g.name=="Maracannes_Exposicao");if(old)UnityEngine.Object.DestroyImmediate(old);
  root=new GameObject("Maracannes_Exposicao").transform;root.gameObject.AddComponent<ExhibitionLink>();points=new List<MuseumPoint>();report=new List<string>();
  SetupMaterials();ImportImages();Envelope();
  var rooms=new[]{Room(1,"História do Maracannes",new Rect(16,-32,16,14)),Room(2,"Filmes · Maracannes 1 e 3 + acervo recebido",new Rect(32,-32,22,20)),Room(3,"2025 · Brasil em Cena",new Rect(32,-12,22,18)),Room(4,"2026 · Memórias da Arte",new Rect(16,-18,16,24))};
  RoomOne(rooms[0]);RoomTwo(rooms[1]);RoomThree(rooms[2]);RoomFour(rooms[3]);
  var catalog=JsonUtility.FromJson<Catalog>(File.ReadAllText(B+"Documentation/posters.json"));
  var slots2=SlotsTwo();var slots3=SlotsThree();int n2=0,n3=0,n4=0;
  foreach(var record in catalog.posters){
   if(record.room==2){var slot=slots2[n2++];Poster(record,slot.Item1,slot.Item2,rooms[1],1.80f);}
   else if(record.room==3){var slot=slots3[n3++];Poster(record,slot.Item1,slot.Item2,rooms[2],2.0f);}
   else {if(n4<2)Poster(record,new Vector3(n4==0?20.3f:27.7f,2.05f,5.83f),Quaternion.identity,rooms[3],2.7f);else Poster(record,new Vector3(16.17f,1.8f,-6),Quaternion.Euler(0,-90,0),rooms[3],.34f,12);n4++;}
  }
  Integrate(teatro);SceneManager.SetActiveScene(scene);
  root.gameObject.AddComponent<ExhibitionRuntimeTest>();
  Physics.SyncTransforms();Validate(catalog,teatro);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene,S);EditorSceneManager.SaveScene(teatro);BuildSettings();AssetDatabase.SaveAssets();
  Capture("Sala_1_Historia",new Vector3(18.4f,1.7f,-25.7f),new Vector3(25,1.6f,-28));
  Capture("Sala_2_Audiovisual",new Vector3(35,1.7f,-25.7f),new Vector3(44,1.7f,-29));
  Capture("Sala_3_Brasil",new Vector3(43,1.7f,-9.5f),new Vector3(44,1.6f,0));
  Capture("Sala_4_Memorias",new Vector3(29,1.7f,-13),new Vector3(23.5f,1.9f,-2));
  File.WriteAllLines(B+"Documentation/construcao.txt",report);AssetDatabase.Refresh();Selection.activeGameObject=root.gameObject;
 }
 static Transform Group(string name,Transform parent=null){var t=new GameObject(name).transform;t.SetParent(parent?parent:root,false);return t;}
 static GameObject Box(string name,Vector3 p,Vector3 size,Material mat,Transform parent=null,bool collision=true){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent?parent:root,false);g.transform.localPosition=p;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;g.isStatic=true;if(!collision)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static GameObject Sphere(string name,Vector3 p,Vector3 size,Material mat,Transform parent){var g=GameObject.CreatePrimitive(PrimitiveType.Sphere);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.isStatic=true;return g;}
 static void Bar(string name,Vector3 a,Vector3 b,float radius,Material mat,Transform parent){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=(a+b)/2;g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,(b-a).normalized);g.transform.localScale=new Vector3(radius*2,Vector3.Distance(a,b)/2,radius*2);g.GetComponent<Renderer>().sharedMaterial=mat;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.isStatic=true;}
 static Material Mat(string name,Color color,float smooth=.1f,float metallic=0){string path=B+"Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.color=color;m.SetFloat("_Smoothness",smooth);m.SetFloat("_Metallic",metallic);m.enableInstancing=true;return m;}
 static void SetupMaterials(){
  wall=Mat("Parede_Cal",new Color(.72f,.70f,.65f));ivory=Mat("Marfim",new Color(.83f,.79f,.68f));graphite=Mat("Grafite_fosco",new Color(.065f,.075f,.08f));brass=Mat("Latao_acetinado",new Color(.54f,.36f,.12f),.32f,.7f);red=Mat("Vinho_cinema",new Color(.17f,.025f,.035f));green=Mat("Verde_Brasil",new Color(.065f,.23f,.17f));ochre=Mat("Ocre",new Color(.72f,.36f,.06f));clay=Mat("Terracota",new Color(.53f,.17f,.075f));foreach(var m in new[]{green,ochre,clay})m.SetFloat("_Cull",0);white=Mat("Papel",new Color(.91f,.88f,.80f));stone=Mat("Pedra_museu",new Color(.48f,.45f,.39f),.2f);
  walnut=Mat("Madeira_museu",new Color(.52f,.36f,.22f),.2f);walnut.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Teatro_Centro_SESI/Textures/fine_grained_wood_diff_1k.jpg");
  light=Mat("Difusor",new Color(1,.9f,.7f));light.EnableKeyword("_EMISSION");light.SetColor("_EmissionColor",new Color(1.4f,1.15f,.8f));
  glass=Mat("Vidro_vitrine",new Color(.65f,.8f,.8f,.12f),.65f);glass.SetFloat("_Surface",1);glass.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);glass.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);glass.SetFloat("_ZWrite",0);glass.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");glass.SetOverrideTag("RenderType","Transparent");glass.renderQueue=3000;
 }
 static void ImportImages(){foreach(var file in Directory.GetFiles(B+"Images","*.png",SearchOption.AllDirectories)){var ti=AssetImporter.GetAtPath(file.Replace('\\','/')) as TextureImporter;if(ti==null)continue;if(ti.npotScale!=TextureImporterNPOTScale.None||ti.maxTextureSize<2048){ti.npotScale=TextureImporterNPOTScale.None;ti.maxTextureSize=file.Contains("S4_002")?8192:2048;ti.mipmapEnabled=true;ti.filterMode=FilterMode.Trilinear;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();}}}
 static Transform Room(int number,string title,Rect rect){var t=Group("Sala_"+number+"_"+title);var room=t.gameObject.AddComponent<MaracannesRoom>();room.number=number;room.theme=title;room.bounds=new Bounds(new Vector3(rect.center.x,1.9f,rect.center.y),new Vector3(rect.width,3.8f,rect.height));
  var floorMat=number==1?walnut:number==2?graphite:stone;
  Box("Laje piso sala "+number,new Vector3(rect.center.x,-.11f,rect.center.y),new Vector3(rect.width,.22f,rect.height),floorMat,t);
  Box("Teto fechado sala "+number,new Vector3(rect.center.x,3.9f,rect.center.y),new Vector3(rect.width,.2f,rect.height),graphite,t);
  // Caixilhos e linhas de teto sustentam as luminárias.
  for(float x=rect.xMin+3;x<rect.xMax-1;x+=5){Box("Trilho contínuo",new Vector3(x,3.73f,rect.center.y),new Vector3(.05f,.07f,rect.height-2),graphite,t,false);for(float z=rect.yMin+3;z<rect.yMax-1;z+=5){Box("Difusor geral",new Vector3(x,3.68f,z),new Vector3(.5f,.035f,.24f),light,t,false);Spot(new Vector3(x,3.62f,z),new Vector3(x,0,z),number==2?new Color(1,.78f,.55f):new Color(1,.93f,.82f),3.2f,9,100,t,false);}}
  if(number>=3){for(float x=rect.xMin+1.5f;x<rect.xMax-.3f;x+=1.5f)Box("Junta discreta do piso",new Vector3(x,.001f,rect.center.y),new Vector3(.006f,.002f,rect.height-.26f),stone,t,false);for(float z=rect.yMin+1.5f;z<rect.yMax-.3f;z+=1.5f)Box("Junta discreta do piso",new Vector3(rect.center.x,.001f,z),new Vector3(rect.width-.26f,.002f,.006f),stone,t,false);}
  return t;
 }
 static void WallX(float x,float z0,float z1,float height,Material mat,Transform parent,float y=0){if(z1-z0>.005f)Box("Parede espessa",new Vector3(x,y+height/2,(z0+z1)/2),new Vector3(.24f,height,z1-z0),mat,parent);}
 static void WallZ(float z,float x0,float x1,float height,Material mat,Transform parent,float y=0){if(x1-x0>.005f)Box("Parede espessa",new Vector3((x0+x1)/2,y+height/2,z),new Vector3(x1-x0,height,.24f),mat,parent);}
 static void OpeningX(float x,float z0,float z1,float door,Transform parent,Material mat){WallX(x,z0,door-1.2f,3.8f,mat,parent);WallX(x,door+1.2f,z1,3.8f,mat,parent);WallX(x,door-1.2f,door+1.2f,.8f,mat,parent,3);Portal(new Vector3(x,0,door),Quaternion.Euler(0,90,0),parent);}
