 static void Envelope(){var t=Group("Estrutura_Continua_Quatro_Salas");WallZ(-32,16,54,3.8f,wall,t);WallZ(6,16,54,3.8f,wall,t);WallX(54,-32,6,3.8f,wall,t);OpeningX(16,-32,6,-25.8f,t,wall);OpeningX(32,-32,-18,-25.8f,t,red);WallX(32,-18,-12,3.8f,wall,t);OpeningX(32,-12,6,-4,t,wall);OpeningZ(-18,16,32,24,t,wall);OpeningZ(-12,32,54,43,t,wall);
  Box("Rodapé fachada sul",new Vector3(35,.085f,-31.86f),new Vector3(37.7f,.17f,.035f),graphite,t,false);Box("Rodapé lateral leste",new Vector3(53.86f,.085f,-13),new Vector3(.035f,.17f,37.7f),graphite,t,false);
