 static void Portal(Vector3 p,Quaternion rot,Transform parent){var t=Group("Portal_aberto",parent);t.position=p;t.rotation=rot;for(int s=-1;s<=1;s+=2)Box("Ombreira",new Vector3(s*1.22f,1.5f,0),new Vector3(.08f,3,.30f),brass,t);Box("Verga",new Vector3(0,3.02f,0),new Vector3(2.52f,.08f,.30f),brass,t);}
 static void Text(string name,string value,Vector3 p,float width,float height,Transform parent,Quaternion? rot=null,Color? color=null){var t=Group(name,parent);t.localPosition=p;t.localRotation=rot??Quaternion.identity;var tm=t.gameObject.AddComponent<TextMesh>();tm.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");tm.text=value;tm.fontSize=80;tm.characterSize=.05f;tm.anchor=TextAnchor.MiddleCenter;tm.alignment=TextAlignment.Center;tm.color=color??new Color(.94f,.90f,.79f);var depth=t.gameObject.AddComponent<MuseumTextDepth>();depth.depthShader=Shader.Find("TeatroSESI/Texto com profundidade");var b=tm.GetComponent<Renderer>().localBounds.size;float scale=Mathf.Min(width/Mathf.Max(b.x,.001f),height/Mathf.Max(b.y,.001f));t.localScale=Vector3.one*scale;}
 static MuseumPoint Info(string title,string body,Vector3 position,Transform parent,string source="Texto e temas fornecidos pelo usuário"){var t=Group("Interacao_"+title,parent);t.position=position;var p=t.gameObject.AddComponent<MuseumPoint>();p.action=MuseumAction.Exhibit;p.title=title;p.body=body;p.source=source;p.radius=2.25f;points.Add(p);return p;}
 static void Plaque(string name,string title,string subtitle,Vector3 p,Quaternion rot,Transform parent,float w=2.4f,float h=.7f,Material mat=null){var t=Group(name,parent);t.position=p;t.rotation=rot;Box("Suporte fixado",Vector3.zero,new Vector3(w,h,.065f),mat?mat:graphite,t,false);Text("Título",title,new Vector3(0,.10f,-.04f),w*.87f,h*.32f,t);Text("Legenda",subtitle,new Vector3(0,-h*.24f,-.04f),w*.87f,h*.18f,t);}
 static void Spot(Vector3 p,Vector3 target,Color color,float intensity,float range,float angle,Transform parent,bool shadow){var t=Group("Foco de galeria",parent);t.position=p;t.LookAt(target);var l=t.gameObject.AddComponent<Light>();l.type=LightType.Spot;l.color=color;l.intensity=intensity;l.range=range;l.spotAngle=angle;l.innerSpotAngle=angle*.65f;l.shadows=shadow?LightShadows.Soft:LightShadows.None;l.shadowBias=.08f;l.shadowNormalBias=.35f;}
 static void RoomOne(Transform t){
  Plaque("Identidade sala 1","01  /  HISTÓRIA DO MARACANNES","ARTE · EDUCAÇÃO · PROTAGONISMO",new Vector3(24,3.18f,-31.80f),Quaternion.Euler(0,180,0),t,10,.7f);
  string[] titles={"O que é o Maracannes?","Maracannes 1 · A origem","Maracannes 3 · Uma nova fase"};string[] body={"O Maracannes Festival de Curta-Metragem do SESI Maracanã é um evento cultural e estudantil que valoriza o talento audiovisual dos alunos. Incentiva a criatividade, a produção e a exibição de curtas. Além do cinema, celebra os talentos do palco, aproximando audiovisual, teatro e outras expressões artísticas.","A primeira edição propôs produzir e exibir curtas baseados em releituras de filmes, com trabalhos em português e inglês. Os estudantes exploraram criação, atuação, roteiro e produção audiovisual, tornando-se protagonistas de suas próprias interpretações do cinema.","A partir do Maracannes 3, cada edição passou a adotar uma proposta temática. Essa nova fase começou com o Maracannes Experience, ampliando as possibilidades criativas e aproximando o festival de experiências artísticas diversificadas."};
  for(int i=0;i<3;i++){float x=20+i*4;var panel=Group("Marco histórico "+(i+1),t);panel.position=new Vector3(x,1.8f,-31.81f);panel.rotation=Quaternion.Euler(0,180,0);Box("Moldura",Vector3.zero,new Vector3(3,1.55f,.065f),walnut,panel,false);Box("Fundo",new Vector3(0,0,-.037f),new Vector3(2.9f,1.45f,.015f),graphite,panel,false);Text("Título",titles[i],new Vector3(0,.48f,-.05f),2.65f,.22f,panel);string[] excerpts={"Cinema, teatro e educação.\nTalento audiovisual dos alunos\ndo SESI Maracanã.","Releituras de filmes, em\nportuguês e inglês. Criação,\natuação e produção estudantil.","Edições temáticas a partir\ndo Maracannes 3, com\no Maracannes Experience."};Text("Resumo histórico",excerpts[i],new Vector3(0,-.02f,-.05f),2.6f,.53f,panel);Text("Interação","[E] LER A HISTÓRIA COMPLETA",new Vector3(0,-.59f,-.05f),2.5f,.12f,panel);Info(titles[i],body[i],new Vector3(x,1.7f,-31.7f),t);Spot(new Vector3(x,3.5f,-30.7f),new Vector3(x,1.7f,-31.8f),new Color(1,.88f,.65f),8,5,60,t,false);}
  for(int s=-1;s<=1;s+=2)Plaque("Arquivo em construção","REGISTROS HISTÓRICOS","Espaço preparado para fotografias e documentos",new Vector3(24+s*4.3f,1.75f,-18.17f),Quaternion.identity,t,3,1.55f,walnut);
  var p=Info("Arte, criatividade e protagonismo","O festival promove trabalho em equipe e oferece aos alunos a oportunidade de compartilhar suas produções com o público. Sua trajetória fortalece as conexões entre educação, cinema, teatro e outras manifestações artísticas. O Maracannes celebra a arte, a educação, a criatividade e o protagonismo estudantil.",new Vector3(24,1.4f,-22.4f),t);
  Pedestal(new Vector3(24,0,-22.4f),new Vector3(1.35f,.85f,1.35f),t);Sculpture("Memória em movimento",new Vector3(24,.86f,-22.4f),t,brass,1.3f);Plaque("Legenda escultura","MEMÓRIA EM MOVIMENTO","Instalação cenográfica da exposição · [E]",new Vector3(24,.57f,-23.1f),Quaternion.identity,t,1.25f,.28f);
  Showcase(new Vector3(19.8f,0,-27.7f),t);Showcase(new Vector3(28.2f,0,-21),t);
  Plaque("Próxima sala","02  →  ACERVO AUDIOVISUAL","Todos os materiais recebidos da pasta da sala 2",new Vector3(31.81f,3.35f,-25.8f),Quaternion.Euler(0,90,0),t,4.4f,.55f);
 }
