 static Material PosterMaterial(Record record){string path=B+"Materials/Cartaz_"+record.id+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Unlit"));AssetDatabase.CreateAsset(m,path);}m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(record.path);m.color=Color.white;return m;}
 static Mesh Store(string name,Mesh mesh){mesh.name=name;mesh.RecalculateNormals();mesh.RecalculateBounds();string path=B+"Models/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);return old;}AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static GameObject MeshObject(string name,Mesh mesh,Material mat,Transform parent){var g=new GameObject(name);g.transform.SetParent(parent,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;g.isStatic=true;return g;}
 static Mesh Quad(string name,float w,float h){return Store(name,new Mesh{vertices=new[]{new Vector3(-w/2,-h/2,0),new Vector3(w/2,-h/2,0),new Vector3(w/2,h/2,0),new Vector3(-w/2,h/2,0)},uv=new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up},triangles=new[]{0,2,1,0,3,2}});}
 static Mesh FlagMesh(){return Store("Bandeirola",new Mesh{vertices=new[]{new Vector3(-.26f,0,0),new Vector3(.26f,0,0),new Vector3(.22f,-.43f,0),new Vector3(0,-.30f,0),new Vector3(-.22f,-.43f,0)},triangles=new[]{0,2,1,0,3,2,0,4,3}});}
 static Mesh Lathe(string name,Vector2[] profile){const int slices=48;var vertices=new List<Vector3>();var uv=new List<Vector2>();var tris=new List<int>();for(int y=0;y<profile.Length;y++)for(int i=0;i<=slices;i++){float a=i*Mathf.PI*2/slices;vertices.Add(new Vector3(Mathf.Cos(a)*profile[y].x,profile[y].y,Mathf.Sin(a)*profile[y].x));uv.Add(new Vector2((float)i/slices,(float)y/(profile.Length-1)));}for(int y=0;y<profile.Length-1;y++)for(int i=0;i<slices;i++){int a=y*(slices+1)+i,b=a+slices+1;tris.AddRange(new[]{a,b,a+1,a+1,b,b+1});}return Store(name,new Mesh{vertices=vertices.ToArray(),uv=uv.ToArray(),triangles=tris.ToArray()});}
 static Mesh Ribbon(string name,float height,float width,float phase){
 var vertices=new List<Vector3>();var uv=new List<Vector2>();var tris=new List<int>();
 for(int i=0;i<=48;i++){float u=i/48f,a=u*3+phase;var c=new Vector3(Mathf.Sin(a)*.3f,u*height,Mathf.Sin(u*4+phase)*.35f);var side=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a))*width*.5f;var thick=new Vector3(-Mathf.Sin(a),0,Mathf.Cos(a))*.025f;foreach(var point in new[]{c-side-thick,c+side-thick,c+side+thick,c-side+thick}){vertices.Add(point);uv.Add(new Vector2(vertices.Count%2,u));}}
 for(int i=0;i<48;i++)for(int face=0;face<4;face++){int a=i*4+face,b=i*4+(face+1)%4,c=a+4,d=b+4;tris.AddRange(new[]{a,c,b,b,c,d});}
 tris.AddRange(new[]{0,1,2,0,2,3,192,194,193,192,195,194});return Store(name,new Mesh{vertices=vertices.ToArray(),uv=uv.ToArray(),triangles=tris.ToArray()});}
