 static void CameraModel(Vector3 p,Transform parent){var source=AssetDatabase.LoadAssetAtPath<GameObject>(B+"Models/PolyHaven_Camera/vintage_video_camera_1k.fbx");if(!source)return;var g=(GameObject)PrefabUtility.InstantiatePrefab(source,scene);g.name="Câmera Poly Haven · CC0";g.transform.SetParent(parent,false);g.transform.localScale=Vector3.one;var renderers=g.GetComponentsInChildren<Renderer>();if(renderers.Length==0)return;var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);float scale=.55f/Mathf.Max(bounds.size.x,bounds.size.y,bounds.size.z);g.transform.localScale=Vector3.one*scale;bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);g.transform.position+=p-new Vector3(bounds.center.x,bounds.min.y,bounds.center.z);var mat=Mat("Camera_PolyHaven",Color.white,.25f,.3f);mat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(B+"Models/PolyHaven_Camera/vintage_video_camera_diff_1k.jpg");foreach(var r in renderers)r.sharedMaterial=mat;}
