 static void Integrate(Scene teatro){
  SceneManager.SetActiveScene(teatro);var all=teatro.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var integration=all.FirstOrDefault(t=>t.name=="Maracannes_Conexao_Foyer");if(integration)UnityEngine.Object.DestroyImmediate(integration.gameObject);var g=new GameObject("Maracannes_Conexao_Foyer");var t=g.transform;
  foreach(string name in new[]{"Parede lateral direita","Lateral direita fechada"}){var original=all.First(x=>x.name==name);original.GetComponent<Renderer>().enabled=false;var collider=original.GetComponent<Collider>();if(collider)collider.enabled=false;var mat=original.GetComponent<Renderer>().sharedMaterial;float x=original.position.x,h=original.localScale.y,z0=original.position.z-original.localScale.z*.5f,z1=original.position.z+original.localScale.z*.5f;
   WallX(x,z0,-27.0f,h,mat,t);WallX(x,-24.6f,z1,h,mat,t);WallX(x,-27,-24.6f,h-2.8f,mat,t,2.8f);
  }
  Box("Piso conexão",new Vector3(14.7f,-.11f,-25.8f),new Vector3(3.3f,.22f,2.4f),stone,t);Box("Teto conexão",new Vector3(14.7f,3.05f,-25.8f),new Vector3(3.3f,.2f,2.4f),wall,t);WallZ(-27,13.5f,16,3.0f,wall,t);WallZ(-24.6f,13.5f,16,3.0f,wall,t);
  Plaque("Entrada Maracannes","MARACANNES  →","EXPOSIÇÃO · QUATRO SALAS",new Vector3(13.34f,2.99f,-25.8f),Quaternion.Euler(0,90,0),t,2.3f,.38f);
  Plaque("Retorno teatro","TEATRO / FOYER  →","SAÍDA DA EXPOSIÇÃO",new Vector3(16.18f,3.35f,-25.8f),Quaternion.Euler(0,-90,0),t,3.8f,.55f);
 }
 static void BuildSettings(){
  var samplePath="Assets/Scenes/SampleScene.unity";var sample=SceneManager.GetSceneByPath(samplePath);if(!sample.isLoaded)sample=EditorSceneManager.OpenScene(samplePath,OpenSceneMode.Additive);if(!sample.GetRootGameObjects().Any(g=>g.GetComponent<MaracannesLoader>())){var g=new GameObject("Maracannes_Carregamento");SceneManager.MoveGameObjectToScene(g,sample);g.AddComponent<MaracannesLoader>();EditorSceneManager.MarkSceneDirty(sample);EditorSceneManager.SaveScene(sample);}
  var settings=EditorBuildSettings.scenes.ToList();foreach(var path in new[]{samplePath,T,S}){var e=settings.FirstOrDefault(x=>x.path==path);if(e==null)settings.Add(new EditorBuildSettingsScene(path,true));else e.enabled=true;}EditorBuildSettings.scenes=settings.ToArray();SceneManager.SetActiveScene(scene);
 }
 static void Validate(Catalog catalog,Scene teatro){var rooms=root.GetComponentsInChildren<MaracannesRoom>();var exhibits=root.GetComponentsInChildren<MaracannesExhibit>();report.Add((rooms.Length==4?"PASS":"FAIL")+" Exatamente quatro salas de exposição");report.Add((exhibits.Length==43?"PASS":"FAIL")+" Todos os 43 materiais expostos: "+exhibits.Length);foreach(int n in new[]{2,3,4})report.Add("Sala "+n+": "+exhibits.Count(e=>e.room==n)+" materiais");int missing=root.GetComponentsInChildren<Renderer>().Count(r=>r.sharedMaterials.Any(m=>!m||!m.shader||m.shader.name.Contains("Error")));report.Add((missing==0?"PASS":"FAIL")+" Materiais e shaders ausentes: "+missing);report.Add("Cenografia original + câmera Poly Haven CC0 (19k tri; textura 1k). Nenhum pacote de input/controlador adicionado.");report.Add("Cartazes: originais preservados; derivados PNG integrais, sem alteração de textos ou proporções.");report.Add("História: exclusivamente texto fornecido pelo usuário; sem datas de fundação inventadas.");report.Add("Teatro preservado. Duas paredes mantidas com render/colisor desabilitados e substituição local segmentada para o portal. Backup anterior disponível.");foreach(var p in catalog.posters)report.Add("ACERVO "+p.id+" → sala "+p.room+" · "+p.title);}
 public static void Capture(string name,Vector3 p,Vector3 target){var g=new GameObject("Captura temporária");var c=g.AddComponent<Camera>();c.transform.position=p;c.transform.LookAt(target);c.fieldOfView=70;c.nearClipPlane=.06f;c.farClipPlane=120;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.1f,.1f,.1f);var rt=new RenderTexture(1600,1000,24);var previous=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;var texture=new Texture2D(1600,1000,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,1600,1000),0,0);texture.Apply();File.WriteAllBytes(B+"Documentation/Evidencias/"+name+".png",texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);}finally{RenderTexture.active=previous;UnityEngine.Object.DestroyImmediate(g);UnityEngine.Object.DestroyImmediate(rt);}}
}
